import{createInstrumentationDispatcher}from"#instrumentation/dispatch.js";function sessionIdempotencyKey(e){return`session:${e}`}function turnIdempotencyKey(e,t){return`turn:${e}:${t}`}function attemptIdempotencyKey(e){return`model-run:${e.sessionId}:${e.runId}:${e.attempt}`}function modelCallIdempotencyKey(e,t,n){return`model:${e.sessionId}:${e.runId}:${e.attempt}:${String(t)}:${String(n)}`}function toolCallIdempotencyKey(e,t,n){return`tool:${e.sessionId}:${e.runId}:${e.attempt}:${t}:${String(n)}`}function inputIdempotencyKey(e,t,n){return`input:${e}:${t}:${n}`}function channelDeliveryIdempotencyKey(e,t){return`channel-delivery:${e}:${t}`}function actionIdempotencyKey(e,t,n){return`action:${e}:${t}:${n}`}const INSTRUMENTATION_PRINCIPAL_TYPES=[`anonymous`,`app`,`local-dev`,`none`,`other`,`runtime`,`service`,`unknown`,`user`];function isInstrumentationPrincipalType(e){return INSTRUMENTATION_PRINCIPAL_TYPES.some(t=>t===e)}function createInstrumentationHooks(e,t={}){return createInstrumentationDispatcher(e,t)}export{INSTRUMENTATION_PRINCIPAL_TYPES,actionIdempotencyKey,attemptIdempotencyKey,channelDeliveryIdempotencyKey,createInstrumentationHooks,inputIdempotencyKey,isInstrumentationPrincipalType,modelCallIdempotencyKey,sessionIdempotencyKey,toolCallIdempotencyKey,turnIdempotencyKey};